SELECT * FROM (
SELECT p.arxiv_id, p.title, p.published, p.topic, p.primary_category FROM papers p WHERE p.year = 2026 AND (p.topic = 'multi-agent-systems' OR EXISTS (SELECT 1 FROM paper_categories pc WHERE pc.arxiv_id = p.arxiv_id AND pc.category = 'cs.MA')) ORDER BY p.published DESC
) LIMIT 51

SELECT * FROM (
SELECT p.arxiv_id, p.title, p.published, p.topic, pc.category FROM papers p JOIN paper_categories pc ON p.arxiv_id = pc.arxiv_id WHERE p.year = 2026 AND (p.topic = 'multi-agent-systems' OR pc.category = 'cs.MA' OR p.title LIKE '%multi-agent%') ORDER BY p.published DESC
) LIMIT 51
